compile.workshop:
variables {
    global:
        0: A
        1: B
}

rule ("else line break") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(A, If-Then-Else(Compare(Global.B, >=, 3), 1, 2));
    }
}

